316	/* Decorative dark auras. These are violet/blue radial washes tuned against a
317	   near-black page; over paper the same gradients read as a dirty grey band
318	   across the top of every hero. Pulled right down rather than removed, so the
319	   heroes keep a hint of colour. */
320	html[data-theme="light"] .hero-aura {
321	  background-image:
322	    radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.07), transparent 70%),
323	    radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.05), transparent 70%);
324	}
325	
326	/* The page ground: the dark theme lights it from above with two radial pools.
327	   Light mode keeps the same geometry at a fraction of the strength — enough to
328	   stop a flat white field, not enough to tint the page. */
329	/* screen/lighten/"lighter"-composite decorations (GlobeBg, AuroraBg,
330	   StreamsBg, PlateBg's plates, and every per-page *Aurora canvas) only ever
331	   ADD light. On a dark page that paints a vivid ribbon or limb; on a light
332	   page there is no black behind it for the colour to emerge from, so it
333	   clips straight toward the page colour and reads as a grey smear over
334	   whatever is there — exactly the "grey radial layer on top of the aurora
335	   streams" reported. That used to mean hiding all of it in light mode
336	   (`.nx-mix-additive`, `display: none`) rather than half-rendering a wash —
337	   but hiding is not a fix, it is losing the decoration outright. The actual
338	   fix is a per-element theme branch instead of a blanket kill switch:
339	     - GlobeBg's planet-limb PNG and PlateBg's raster plates have real
340	       colour to fall back on, so they swap "screen"/"lighten" for normal
341	       blending at a lower opacity in light mode — see `.nx-globe-arc` below
342	       and `.nx-plate-additive`.
343	     - The canvas auroras (AuroraBg, StreamsBg, every *Aurora.tsx component)
344	       have no such fallback image, so they read the active theme once per
345	       animation frame in JS and switch `globalCompositeOperation` to
346	       "source-over" with darker, higher-alpha stops — see auroraTheme.ts.
347	       Nothing in this stylesheet needs to hide them any more. */
348	html[data-theme="light"] .nx-globe-arc { mix-blend-mode: normal !important; opacity: 0.4 !important; }
349	
350	/* PlateBg's screen/lighten raster plates — same fix as .nx-globe-arc, for the
351	   same reason: these are real images, so light mode swaps the blend mode
352	   instead of hiding the plate. */
353	html[data-theme="light"] .nx-plate-additive { mix-blend-mode: normal !important; opacity: 0.4 !important; }
354	
355	/* The "BUILD / HOST / SCALE / ANYWHERE" deploy-wizard lockup. Base (dark)
356	   values match what used to be inline on the component. */
357	.nx-play-lockup { color: #c6daf4; text-shadow: 0 1px 6px rgba(0,6,22,0.95); }
358	/* A pale ice-blue with a dark contact-shadow, both tuned for sitting on a dark
359	   hero — the colour was nearly invisible on a light page and the shadow read
360	   as a smudge rather than adding contrast. */
361	html[data-theme="light"] .nx-play-lockup {
362	  color: var(--color-blue);
363	  text-shadow: none;
364	}
365	
366	html[data-theme="light"] body {
367	  background-image:
368	    radial-gradient(920px 540px at 88% -12%, rgba(0, 80, 242, 0.07), transparent 62%),
369	    radial-gradient(700px 460px at 6% 108%, rgba(120, 40, 220, 0.05), transparent 66%);
370	}
371	
372	/* ── dark islands ──────────────────────────────────────────────────────────
373	   The rail and the top bar stay dark in both themes. Rather than hard-coding
374	   colours into those two components, they re-declare the DARK token values on
375	   themselves, so their whole subtree — nav rows, the balance card, the search
376	   field, the account block — inherits dark without any of it knowing a theme
377	   exists. */
378	/* ══ The rest of the app ═════════════════════════════════════════════════
379	   This redesign covers the VPS panel; ~18 other files across Settings,
380	   Support, Directory, Migrate, Services and the game panel (which the VPS
381	   panel's own look was modelled on) use the SAME hand-written idiom: a card
382	   is `bg-[linear-gradient(180deg,rgba(10,22,48,N),rgba(2,7,20,N))]` with a
383	   `text-white` heading inside it, tuned only ever against a dark page. Editing
384	   every one of those files individually is a much larger change than this
385	   pass — these three rules retarget the pattern itself, wherever it appears,
386	   for light mode only. Dark mode does not match any of these selectors and is
387	   completely unaffected.
388	
389	   The attribute selector matches the literal characters Tailwind puts in the
390	   `class` DOM attribute, which is unescaped there even though the generated
391	   CSS selector for the same class has to escape the brackets and commas — so
392	   `[class*="rgba(10,22,48"]` finds it without needing to know the exact
393	   opacity any given instance used. */
394	html[data-theme="light"] [class*="rgba(10,22,48"] {
395	  background-image: linear-gradient(180deg, rgba(255,255,255,.92), rgba(246,249,253,.98)) !important;
396	  border-color: var(--color-rim);
397	}
398	html[data-theme="light"] [class*="rgba(6,14,36"] {
399	  background: rgba(255,255,255,.85) !important;
400	}
401	html[data-theme="light"] [class*="rgba(4,11,30"] {
402	  background: #ffffff !important;
403	  border-color: var(--color-rim) !important;
404	}
405	/* A `text-white` heading is only ever meant as "the readable ink colour" in
406	   these components — never a colour chosen to sit on a saturated brand
407	   surface, which is what the VPS panel's own remaining `text-white` spots are
408	   (and why those were fixed by hand instead of matched here). Scoped to
409	   descendants of the two card patterns above, so nothing outside them moves. */
410	html[data-theme="light"] [class*="rgba(10,22,48"] [class~="text-white"],
411	html[data-theme="light"] [class*="rgba(6,14,36"] [class~="text-white"],
412	html[data-theme="light"] [class*="rgba(4,11,30"][class~="text-white"] {
413	  color: var(--color-tx) !important;
414	}
415	/* The same subtle-wash idiom my own first pass used before it was fixed
416	   properly — `bg-white/[0.0N]` as a lightener calibrated for a dark card.
417	   One flat treatment for all of them rather than one rule per opacity: the
418	   original values were never trying to be precise, only subtle. */
419	html[data-theme="light"] [class*="bg-white/[0.0"] {
420	  background-color: color-mix(in srgb, var(--fg) 6%, transparent) !important;
421	}
422	
423	/* The general form of the same fix, for every file this pass did not open.
424	   `text-white`/`bg-white`/`border-white` (bare, 100% opacity) are headings and
425	   want ink — that is what flipping the token above does. Anything with a
426	   slash after "white" is an OPACITY variant — `white/10`, `white/[0.04]`,
427	   `hover:bg-white/20` — and those want a wash relative to whatever the
428	   surface actually is now, not a tint of ink-through-transparency. Matched on
429	   the raw class attribute text, so it does not matter which prefix (hover:,
430	   sm:, etc.) precedes the utility. Gradient stop utilities (from-white/N,
431	   via-white/N, to-white/N) are not covered — those set a custom property
432	   rather than a plain CSS property, so there is no single declaration to
433	   override this way; decorative sheens, not text, so lower cost left as is. */
434	/* Islands are EXCLUDED at the selector, not overridden after the fact —
435	   `revert` does not mean "the value this same rule would have skipped", it
436	   rolls back to a different cascade origin entirely, so it cannot undo an
437	   `!important` sibling rule. `:not()` accepts a full selector list including
438	   descendant combinators, so this reads as "matches, and is not the island and
439	   is not inside one" in one step. Inside dark chrome, "white at 10% opacity on
440	   dark" is already correct in both themes and must stay untouched. */
441	html[data-theme="light"] [class*="bg-white/"]:not(.nx-dark-island, .nx-dark-island *) {
442	  background-color: color-mix(in srgb, var(--fg) 7%, transparent) !important;
443	}
444	html[data-theme="light"] [class*="border-white/"]:not(.nx-dark-island, .nx-dark-island *) {
445	  border-color: color-mix(in srgb, var(--fg) 16%, transparent) !important;
446	}
447	html[data-theme="light"] [class*="text-white/"]:not(.nx-dark-island, .nx-dark-island *) {
448	  color: color-mix(in srgb, var(--fg) 68%, transparent) !important;
449	}
450	
451	/* Calendar's date/time inputs (EventModal, TaskPanel) carry a literal
452	   `[color-scheme:dark]` utility so their native picker icon and dropdown
453	   chrome read correctly against the (then only) dark theme. Left alone, that
454	   forces a dark-styled calendar/clock glyph onto what is now a plain white
455	   `.input` in light mode. Match the surface it is actually sitting on instead
456	   of the hardcoded scheme — `.nx-dark-island` below still wants real dark
457	   chrome and is excluded the same way the rules above are. */
458	html[data-theme="light"] [class*="color-scheme:dark"]:not(.nx-dark-island, .nx-dark-island *) {
459	  color-scheme: light;
460	}
461	
462	html[data-theme="light"] .nx-dark-island {
463	  color-scheme: dark;
464	
465	  --color-void: #00060f;
466	  --color-bg: #000816;
467	  --color-surface: #010f22;
468	  --color-well: #000c1e;
469	  --color-hover: #021428;
470	  --color-side: #00081a;
471	  --color-rim: #002049;
472	  --color-rim-soft: #00173b;
473	  --color-rim-hi: #002a5e;
474	
475	  /* Missed the first time: anything inside the rail or top bar using
476	     bg-navy-900/whatever (the currency switcher, among others) fell through
477	     to the ROOT light-theme navy value — near-white — at whatever opacity the
478	     component asked for, over a dark header. That reads as a grey smear,
479	     which is exactly the reported bug. */
480	  --color-navy-950: #000816;
481	  --color-navy-900: #010f22;
482	  --color-navy-850: #021428;
483	  --color-navy-800: #00152f;
484	  --color-navy-700: #002049;
485	  --color-navy-600: #002a5e;
486	  --color-white: #ffffff;
487	
488	  --color-brand-500: #8c3ae9;
489	  --color-brand-400: #a05cf0;
490	  --color-brand-300: #b785f2;
491	  --color-accent-blue: #2f7eef;
492	  --color-accent-cyan: #14c5e4;
493	  --color-cyan: #14c5e4;
494	  --color-blue: #2f7eef;
495	  --color-violet: #8c3ae9;
496	  --color-magenta: #d623e1;
497	  --color-mint: #11c88e;
498	  --color-amber: #efa828;
499	  --color-rose: #ef426c;
500	
501	  --color-slate-50: #ffffff;
502	  --color-slate-100: #eaf2ff;
503	  --color-slate-200: #d8e6ff;
504	  --color-slate-300: #cbdcff;
505	  --color-slate-400: #93aede;
506	  --color-slate-500: #7f9ad0;
507	  --color-slate-600: #5f7cb4;
508	  --color-slate-700: #2b4a80;
509	  --color-slate-800: #001a3d;
510	  --color-slate-900: #00102a;
511	  --color-slate-950: #000816;
512	
513	  --color-tx: #ffffff;
514	  --color-tx-body: #cbdcff;
515	  --color-tx-mute: #93aede;
516	  --color-tx-dim: #7f9ad0;
517	  --color-tx-faint: #5f7cb4;
518	
519	  --fg: #ffffff;
520	  --fg-muted: #94a3b8;
521	
522	  /* Islands paint an opaque ground. Their own classes are translucent
523	     (`bg-side/80`, `bg-bg/70`) so that the dark page shows through in dark
524	     mode; over a light page that same transparency let white through and made
525	     them read grey. This puts a solid dark plate behind them. */
526	  background-color: #00081a;
527	
528	  /* The islands are still dark, so white is white again inside them. */
529	  --color-white: #ffffff;
530	
531	  /* An inherited colour, not just tokens. `body` carries `text-slate-300` and
532	     sits OUTSIDE every island, so any element inside one that does not set its
533	     own colour — most headings do not — was inheriting the LIGHT ink straight
534	     past the island's token overrides. Restating it here gives the subtree a
535	     dark-theme default to inherit from. */
536	  color: #cbdcff;
537	}
538	
539	/* /admin and /staff keep the original design. The shell there carries
540	   `.nx-dark-island`, but the page GROUND is painted on <body>, outside it — so
541	   without this the chrome would be dark on a light field. */
542	html[data-theme="light"]:has(.nx-dark-island.min-h-screen) body {
543	  background-color: #000816;
544	  background-image:
545	    radial-gradient(920px 540px at 88% -12%, rgba(0, 80, 242, 0.15), transparent 62%),
546	    radial-gradient(700px 460px at 6% 108%, rgba(80, 40, 220, 0.11), transparent 66%);
547	}
548	
549	/* ── surfaces that draw their own colour ───────────────────────────────────
550	   A handful of components paint gradients or translucent fills directly rather
551	   than through a token. Those need a light counterpart; everything else is
552	   already correct from the swap above. */
553	
554	/* .card's border is a dark blue gradient in border-box. On paper that reads as
555	   a dirty outline, so light mode takes a plain rim and a real shadow instead —
556	   depth from the lift, not from the edge. */
557	/* :not(.card-on) — the selected-plan card (game/VPS deploy wizard) paints its
558	   own rainbow conic-gradient rim and dark fill regardless of theme, same idea
559	   as an nx-dark-island. This rule has higher specificity than `.card-on`
560	   alone (html + class + :not() beats one class), so without the exclusion it
561	   silently overwrote the selected treatment with the plain unselected card
562	   style — every plan card looked identical and nothing showed as picked. */
563	html[data-theme="light"] .card:not(.nx-dark-island .card):not(.card-on) {
564	  background: var(--color-surface);
565	  border: 1px solid var(--color-rim);
566	  box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 14px 32px -22px rgb(15 23 42 / 0.30);
567	}
568	html[data-theme="light"] .card-i:hover:not(.card-on) {
569	  background: #ffffff;
570	  border-color: color-mix(in srgb, var(--color-brand-500) 34%, transparent);
571	  box-shadow: 0 2px 4px rgb(15 23 42 / 0.06), 0 18px 38px -20px rgb(15 23 42 / 0.34);
572	}
573	/* .card-on itself is excluded above (it keeps its own rainbow rim in both
574	   themes), but its DARK #04214f fill — fine floating among other dark cards —
575	   reads as a jarring solid-navy hole punched into an otherwise all-white plan
576	   grid in light mode ("the highlight card is not look good"). Keep the same
577	   travelling conic-gradient rim (the part that actually reads as "selected")
578	   and swap only the fill and glow for a light surface. */
579	html[data-theme="light"] .card-on {
580	  background:
581	    linear-gradient(#fff, #fff) padding-box,
582	    conic-gradient(from var(--orbit),
583	      #14c5e4 0deg, #6be6ff 40deg, #2f7eef 100deg,
584	      #8c3ae9 170deg, #d623e1 215deg, #ff8cf2 255deg,
585	      #8c3ae9 300deg, #14c5e4 360deg) border-box;
586	  box-shadow: inset 0 0 16px -8px rgba(20,197,228,0.16),
587	              0 0 20px -10px rgba(20,197,228,0.35),
588	              0 0 26px -12px rgba(214,35,225,0.28),
589	              0 10px 26px rgba(15,23,42,0.14);
590	}
591	
592	/* Glass over a light page needs a fill to be glass at all — fully transparent
593	   on white is just white. A high-key wash keeps the blur legible. */
594	html[data-theme="light"] .card-glass {
595	  background: rgba(255, 255, 255, 0.66);
596	  border-color: color-mix(in srgb, var(--tone) 42%, transparent);
597	  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.12);
598	}
599	html[data-theme="light"] .card-glass::before { opacity: 0.55; }

