import { chromium } from "playwright";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
const page = await ctx.newPage();

page.on("console", (m) => console.log("CONSOLE:", m.text()));
page.on("response", (r) => {
  if (r.url().includes("login") || r.url().includes("auth")) {
    console.log("RESPONSE:", r.status(), r.url());
  }
});

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
await page.waitForTimeout(1000);
// dismiss cookie banner if present
try {
  await page.click('button:has-text("Got it")', { timeout: 3000 });
  console.log("dismissed cookie banner");
} catch { console.log("no cookie banner"); }

await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
console.log("filled form, clicking...");
await page.click("button.btn-primary");
await page.waitForTimeout(5000);
console.log("URL after click+wait:", page.url());
await page.screenshot({ path: "/tmp/audit-b2/debug-after-login.png", fullPage: true });
await browser.close();

// Audit screenshot script for assigned pages: billing, invoices, affiliate,
// partner, team, feedback, whats-new. Captures dark (default) and light mode
// for each. Retries login/nav since the shared v2 service restarts under other
// parallel agents' rebuilds. Temporary — delete when audit is done.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-b2";
mkdirSync(out, { recursive: true });

const PATHS = [
  "/dashboard/billing",
  "/dashboard/invoices",
  "/dashboard/affiliate",
  "/dashboard/partner",
  "/dashboard/team",
  "/dashboard/feedback",
  "/dashboard/whats-new",
];

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

async function login() {
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded", timeout: 30000 });
      await page.waitForTimeout(800);
      try { await page.click('button:has-text("Got it")', { timeout: 2000 }); } catch {}
      await page.fill('input[type="email"], input[name="email"]', EMAIL, { timeout: 10000 });
      await page.fill('input[type="password"], input[name="password"]', PASS, { timeout: 10000 });
      await page.click("button.btn-primary", { timeout: 10000 });
      await page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 20000 });
      await page.waitForTimeout(500);
      console.log(`login ok (attempt ${attempt})`);
      return true;
    } catch (e) {
      console.log(`login attempt ${attempt} failed: ${e.message.split("\n")[0]}`);
      await page.waitForTimeout(4000);
    }
  }
  return false;
}

async function gotoResilient(url) {
  for (let attempt = 1; attempt <= 4; attempt++) {
    try {
      await page.goto(url, { waitUntil: "networkidle", timeout: 45000 });
    } catch {
      await page.waitForTimeout(2000);
    }
    const bodyText = await page.evaluate(() => document.body?.innerText?.slice(0, 30) || "").catch(() => "");
    if (bodyText.includes("502 Bad Gateway") || page.url().includes("/login")) {
      console.log(`  nav attempt ${attempt} landed on ${page.url().includes("/login") ? "login" : "502"} for ${url}, retrying...`);
      await page.waitForTimeout(4000);
      if (page.url().includes("/login") && !page.url().includes(url)) {
        // session dropped — re-login
        await login();
      }
      continue;
    }
    return true;
  }
  return false;
}

const ok = await login();
if (!ok) {
  console.error("could not log in after retries");
  process.exit(1);
}

let invoiceHref = null;

for (const theme of ["dark", "light"]) {
  for (const p of PATHS) {
    const slug = p.replace(/^\//, "").replace(/[^a-z0-9]+/gi, "-") || "root";
    await gotoResilient(`${BASE}${p}`);
    if (theme === "light") {
      await page.evaluate(() => {
        localStorage.setItem("nx-theme", "light");
        document.documentElement.setAttribute("data-theme", "light");
      });
    } else {
      await page.evaluate(() => {
        localStorage.removeItem("nx-theme");
        document.documentElement.removeAttribute("data-theme");
      });
    }
    await page.waitForTimeout(1800);
    if (p === "/dashboard/invoices" && !invoiceHref) {
      try {
        invoiceHref = await page.locator('a[href^="/dashboard/invoices/"]').first().getAttribute("href", { timeout: 3000 });
      } catch {}
    }
    const file = join(out, `${theme}-${slug}.png`);
    await page.screenshot({ path: file, fullPage: true });
    console.log(`${theme} ${p} -> ${file}`);
  }
  if (invoiceHref) {
    await gotoResilient(`${BASE}${invoiceHref}`);
    if (theme === "light") {
      await page.evaluate(() => {
        localStorage.setItem("nx-theme", "light");
        document.documentElement.setAttribute("data-theme", "light");
      });
    }
    await page.waitForTimeout(1500);
    const file = join(out, `${theme}-invoice-detail.png`);
    await page.screenshot({ path: file, fullPage: true });
    console.log(`${theme} ${invoiceHref} -> ${file}`);
  } else {
    console.log("no invoice found to open detail page");
  }
}

await browser.close();

