// Drive the Team page: create an org (if none), then screenshot each tab and
// the invite modal in dark + light. Temporary — delete when audit is done.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-b2";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 } });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
try { await page.click('button:has-text("Got it")', { timeout: 2000 }); } catch {}
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await page.click("button.btn-primary");
await page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 30000 });

await page.goto(`${BASE}/dashboard/team`, { waitUntil: "networkidle", timeout: 45000 });
await page.waitForTimeout(1000);

// Create org if the empty state is showing.
const createBtn = page.locator('button:has-text("Create organization")');
if (await createBtn.isVisible().catch(() => false)) {
  await page.fill('input[placeholder*="Organization name"]', "Nexion Audit Co");
  await createBtn.click();
  await page.waitForTimeout(2000);
}

async function shotTabs(theme) {
  await page.reload({ waitUntil: "networkidle" });
  if (theme === "light") {
    await page.evaluate(() => {
      localStorage.setItem("nx-theme", "light");
      document.documentElement.setAttribute("data-theme", "light");
    });
  }
  await page.waitForTimeout(1000);
  const tabs = ["members", "invites", "roles", "activity", "settings"];
  for (const t of tabs) {
    const btn = page.locator(`button:has-text("${t === "members" ? "Members" : t === "invites" ? "Invites" : t === "roles" ? "Roles" : t === "activity" ? "Activity" : "Organisation Settings"}")`).first();
    if (await btn.isVisible().catch(() => false)) {
      await btn.click();
      await page.waitForTimeout(500);
      await page.screenshot({ path: join(out, `${theme}-team-${t}.png`), fullPage: true });
      console.log(`${theme} team/${t} captured`);
    } else {
      console.log(`${theme} team/${t} tab not visible`);
    }
  }
  // Invite modal
  const inviteBtn = page.locator('button:has-text("Invite Member")').first();
  if (await inviteBtn.isVisible().catch(() => false)) {
    await inviteBtn.click();
    await page.waitForTimeout(500);
    await page.screenshot({ path: join(out, `${theme}-team-invite-modal.png`), fullPage: true });
    console.log(`${theme} team invite modal captured`);
    await page.keyboard.press("Escape");
    await page.waitForTimeout(300);
  }
}

await shotTabs("dark");
await shotTabs("light");

await browser.close();

