import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-b2";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 } });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
try { await page.click('button:has-text("Got it")', { timeout: 2000 }); } catch {}
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await page.click("button.btn-primary");
await page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 30000 });

async function shotBillingTabsAndModals(theme) {
  await page.goto(`${BASE}/dashboard/billing`, { waitUntil: "networkidle" });
  if (theme === "light") {
    await page.evaluate(() => {
      localStorage.setItem("nx-theme", "light");
      document.documentElement.setAttribute("data-theme", "light");
    });
  } else {
    await page.evaluate(() => {
      localStorage.removeItem("nx-theme");
      document.documentElement.removeAttribute("data-theme");
    });
  }
  await page.waitForTimeout(800);

  // Billing settings tab
  await page.click('button:has-text("Billing settings")');
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(out, `${theme}-billing-settings.png`), fullPage: true });
  console.log(`${theme} billing-settings captured`);

  // Usage tab
  await page.click('button:has-text("Usage")');
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(out, `${theme}-billing-usage.png`), fullPage: true });
  console.log(`${theme} billing-usage captured`);

  // Add funds modal - look for "Add funds" button inside settings tab (form, not modal maybe)
  await page.click('button:has-text("Billing settings")');
  await page.waitForTimeout(400);
  // AddCardButton "Add another card"
  const addCardBtn = page.locator('button:has-text("Add another card"), button:has-text("Add a card")').first();
  if (await addCardBtn.isVisible().catch(() => false)) {
    await addCardBtn.click();
    await page.waitForTimeout(700);
    await page.screenshot({ path: join(out, `${theme}-billing-addcard-modal.png`), fullPage: true });
    console.log(`${theme} billing-addcard-modal captured`);
    await page.keyboard.press("Escape").catch(() => {});
    await page.waitForTimeout(300);
  } else {
    console.log(`${theme} add card button not visible`);
  }
}

await shotBillingTabsAndModals("dark");
await shotBillingTabsAndModals("light");

await browser.close();

