185	function ServiceTag({ type }: { type: string }) {
186	  const meta = SERVICE_META[type];
187	  if (!meta) return null;
188	  return (
189	    <span className="chip-q">
190	      <ServiceIcon icon={meta.icon} size={11} />
191	      {meta.label}
192	    </span>
193	  );
194	}
