6	export function AutoRecharge({
7	  enabled: initialEnabled,
8	  thresholdCents,
9	  amountCents,
10	}: {
11	  enabled: boolean;
12	  thresholdCents: number | null;
13	  amountCents: number | null;
14	}) {
15	  const [state, action, pending] = useActionState(
16	    saveAutoRecharge,
17	    {} as { ok?: boolean; error?: string }
18	  );
19	  const [enabled, setEnabled] = useState(initialEnabled);
20	
21	  const toDollars = (c: number | null, fallback: string) =>
22	    c !== null ? (c / 100).toFixed(2) : fallback;
23	
24	  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
25	  // `<form action={fn}>` submit, and `saveAutoRecharge` rejects with
26	  // "Recharge amount must be at least $5.00 when auto-recharge is on."
27	  // (lib/actions-billing-prefs.ts:40). With `defaultValue` the field the
28	  // customer has to correct snapped back to the STORED value the instant they
29	  // were told to correct it — so the message pointed at a number that was no
30	  // longer on screen, and pressing Save again quietly re-saved the old figures
31	  // while looking like it had taken the new ones.
32	  const [threshold, setThreshold] = useState(() => toDollars(thresholdCents, "5.00"));
33	  const [amount, setAmount] = useState(() => toDollars(amountCents, "25.00"));
34	
35	  return (
36	    <form action={action} className="space-y-4">
37	      <label className="flex items-center gap-3 text-sm">
38	        <input
39	          type="checkbox"
40	          name="enabled"
41	          checked={enabled}
42	          onChange={(e) => setEnabled(e.target.checked)}
43	        />
44	        <span className="font-medium">Automatically top up my wallet</span>
45	      </label>
46	
47	      <div className={`grid gap-3 sm:grid-cols-2 ${enabled ? "" : "pointer-events-none opacity-50"}`}>
48	        <div>
49	          <label className="label" htmlFor="auto-recharge-threshold">
50	            When balance drops below (USD)
51	          </label>
52	          <input
53	            id="auto-recharge-threshold"
54	            className="input"
55	            name="threshold"
56	            type="number"
57	            min={0}
58	            step="0.01"
59	            value={threshold}
60	            onChange={(e) => setThreshold(e.target.value)}
61	            disabled={!enabled}
62	          />
63	        </div>
64	        <div>
65	          <label className="label" htmlFor="auto-recharge-amount">
66	            Top up by (USD)
67	          </label>
68	          <input
69	            id="auto-recharge-amount"
70	            className="input"
71	            name="amount"
72	            type="number"
73	            min={5}
74	            step="0.01"
75	            value={amount}
76	            onChange={(e) => setAmount(e.target.value)}
77	            disabled={!enabled}
78	          />
79	          <p className="mt-1 text-xs text-slate-500">Minimum $5.00 while auto-recharge is on.</p>
80	        </div>
81	      </div>
82	
83	      <div className="flex flex-wrap items-center gap-3">
84	        <button className="btn-primary" disabled={pending}>
85	          {pending ? "Saving…" : "Save preferences"}
86	        </button>
87	        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
88	        {state?.ok && <span className="text-sm text-emerald-300">Preferences saved.</span>}
89	      </div>
90	
91	      <p className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
92	        Requires a saved card — charging is handled automatically once a payment method is on file.
93	      </p>
94	    </form>
95	  );
96	}
