4	import { redeemGiftCode } from "@/lib/actions-gift";
5	import { fmtMoney } from "@/components/ui/primitives";
6	
7	export function RedeemGift() {
8	  const [code, setCode] = useState("");
9	  const [error, setError] = useState<string | null>(null);
10	  const [success, setSuccess] = useState<{ amountCents: number } | null>(null);
11	  const [pending, start] = useTransition();
12	
13	  const redeem = () => {
14	    setError(null);
15	    setSuccess(null);
16	    const trimmed = code.trim();
17	    if (!trimmed) {
18	      setError("Enter a code.");
19	      return;
20	    }
21	    start(async () => {
22	      const res = await redeemGiftCode(trimmed);
23	      if (res.ok) {
24	        setSuccess({ amountCents: res.amountCents ?? 0 });
25	        setCode("");
26	      } else {
27	        setError(res.error ?? "Couldn't redeem that code.");
28	      }
29	    });
30	  };
31	
32	  return (
33	    <div>
34	      <div className="flex flex-wrap items-end gap-2">
35	        <div className="flex-1">
36	          <label className="label">Gift or promo code</label>
37	          <input
38	            className="input w-full font-mono uppercase"
39	            value={code}
40	            onChange={(e) => {
41	              setCode(e.target.value);
42	              if (error) setError(null);
43	            }}
44	            placeholder="NXEON-XXXX-XXXX or FREEMONTH"
45	            maxLength={32}
46	            onKeyDown={(e) => {
47	              if (e.key === "Enter") {
48	                e.preventDefault();
49	                redeem();
50	              }
51	            }}
52	          />
53	        </div>
54	        <button type="button" className="btn-primary" onClick={redeem} disabled={pending}>
55	          {pending ? "Redeeming…" : "Redeem"}
56	        </button>
57	      </div>
58	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
59	      {success && (
60	        <p className="mt-2 text-sm text-emerald-300">
61	          Success — {fmtMoney(success.amountCents)} added to your wallet.
62	        </p>
63	      )}
64	      {!error && !success && (
65	        <p className="mt-2 text-xs text-slate-500">
66	          Redeem a prepaid code to add credit to your wallet balance.
67	        </p>
68	      )}
69	    </div>
70	  );
71	}
